# -*- coding: utf-8 -*-
"""Capítulos 8-14 del Nivel 1 de NVDA (revisión NVDA-20261101-A12-R1)."""
from analisis_nvda_20261101_parte1 import *

VBr = lambda i: VB[i]
def vrow(i): return VB[i][2:12]
sc_ratio = vrow(37); inv_cap = vrow(38); roic = vrow(39)
tcf = VB[15][1]; tv = VB[17][1]; pvtv = VB[18][1]; pv10 = VB[19][1]
wacc0 = V['tasas']['wacc']; waccT = V['tasas']['waccTerminal']
rein = [p['reinvestment'] for p in proy]

SD3 = V['sensibilidadDCF']['matrices']['crecimientoVsMargen']; SD1 = V['sensibilidadDCF']['matrices']['waccVsTerminalGrowth']
DV_G = (SD3['values'][3][2] - SD3['values'][2][2]) / ((SD3['rows'][3] - SD3['rows'][2]) * 100)
DV_M = (SD3['values'][2][3] - SD3['values'][2][2]) / ((SD3['columns'][3] - SD3['columns'][2]) * 100)
DV_W_UP = SD1['values'][3][2] - SD1['values'][2][2]; DV_W_DN = SD1['values'][1][2] - SD1['values'][2][2]
DV_G_LO = SD1['values'][2][1] - SD1['values'][2][2]; DV_G_HI = SD1['values'][2][3] - SD1['values'][2][2]

def mult_row(tab, name):
    t = D['mult_' + tab]
    return [t[7][7], t[18][7], t[29][7]]   # H8, H19, H30 = múltiplo de salida FY+3 Cons/Base/Opt
MT = {'EV/EBITDA': 'EVEBITDA', 'EV/FCFF': 'EVFCFF', 'P/E': 'PE', 'P/FCFE': 'PFCFE', 'P/OCF': 'POCF'}
TV = D['trailing']
ltm_mult = {'EV/EBITDA': TV[20][11], 'EV/FCFF': TV[23][11], 'P/E': TV[12][11], 'P/FCFE': TV[15][11], 'P/OCF': TV[14][11]}

def cap8():
    rows = [[f'Año {i+1}', n(proy[i]['revenues']), n(rein[i]), n(sc_ratio[i], 2), n(inv_cap[i]), pc(roic[i], 0)] for i in (0, 1, 2, 4, 9)]
    return chapter(8, 'Reinversión, capital invertido y Sales-to-Capital',
    P('La reinversión es el puente entre el crecimiento y el flujo libre: una empresa que quiere crecer ingresos debe invertir capital (fábricas, capital de trabajo, tecnología), y lo que queda después de esa inversión es lo que se descuenta. En el Método A-1.2 la reinversión de cada año es el incremento de ingresos del año siguiente dividido por la razón ventas/capital (Sales-to-Capital), con un año de desfase. Así, en el año 1, la reinversión es ' + n(rein[0]) + ' millones, que equivale al aumento de ingresos del año 2 (' + n(proy[1]['revenues'] - proy[0]['revenues']) + ' millones) dividido por 2,2.'),
    table(['Año', 'Ingresos', 'Reinversión', 'Ventas/capital', 'Capital invertido', 'ROIC'], rows, 'Reinversión y retorno en la historia Base (hoja Valuation output).'),
    '<h3>Por qué 2,2 y por qué 0,7</h3>' + P(
      f'La razón ventas/capital de 2,2 en los años 1 a 5 mide cuántos dólares de ingreso adicional compra cada dólar de capital incremental. La hoja la fija en 2,2 (Conservadora 1,4, Optimista 2,8, Disrupción 0,85) y luego la baja a 0,7 en los años 6 a 10 (0,62, 0,78 y 0,65). La razón del descenso es económica: en la fase de expansión, el capital incremental es sobre todo capital de trabajo y activos intangibles de bajo peso; en la fase madura, el crecimiento exige capacidad física y adquisiciones más intensivas. Un 0,7 equivale a que cada dólar adicional de ingreso exige 1,43 dólares de capital; es la hipótesis del modelo para la fase madura, no una cifra observada en NVIDIA. El ROIC resultante cae de {pc(roic[0],0)} en el año 1 a {pc(roic[9],0)} en el año 10 y converge a {pc(base[6],1)} en el terminal.'),
    '<h3>Lo que el indicador no captura: compromisos de suministro</h3>' + P(
      'Un hecho central de este expediente es que NVIDIA ha aumentado sus compromisos de suministro y capacidad de 119.000 millones en el trimestre anterior a 279.000 millones al 26 de julio de 2026, una cifra comparable a todos los ingresos LTM (302.970 millones). Esos compromisos son obligaciones de compra de obleas, memoria, empaquetado y ensamblaje; no son capex físico de NVIDIA ni aparecen como activo, y se pagan con los ingresos de los clientes que los motivan. Lo correcto es tratarlos como una exposición a riesgo de inventario y de capacidad, no como reinversión adicional: añadirlos a la inversión del DCF duplicaría el costo, porque el costo de los productos que se fabrican con ellos ya está en el costo de ventas y en el capital de trabajo. Sin embargo, sí amplifican la pérdida si la demanda se frena: el 10-Q ya registra 2.138 millones de obligaciones de compra de inventario en exceso y provisiones por 4.500 millones relacionadas con H20 en el primer trimestre del año fiscal 2026. Esta es una razón para no usar valores de ventas/capital superiores a 2,2 en el Base y para mantener la Disrupción con 0,85.'),
    '<h3>Capital de trabajo y activos estratégicos</h3>' + P(
      'En el semestre los inventarios crecieron 10.204 millones y las cuentas por cobrar 24.590 millones, mientras las cuentas por pagar y los pasivos acumulados aportaron 12.140 millones: el capital de trabajo absorbió unos 22.600 millones de los 74.421 millones de flujo operativo de la mitad del año. Los 42.404 millones comprados en valores de capital y la inversión en infraestructura de terceros no son reinversión operativa: se tratan como inversiones no operativas con valor igual a su valor contable (capítulo 12) y cualquier retorno que generen está fuera del EBIT. Es una decisión relevante, porque la compañía las financia con la misma caja que podría haber devuelto al accionista.'),
    P(f'El valor terminal usa un flujo de {n(tcf)} millones, un costo de capital de {pc(waccT,2)} y una tasa de reinversión implícita de {pc(base[9]/base[6],1)} (g dividido por el ROIC terminal). Su valor presente es {n(pvtv)} millones, el {pc(tv_share,1)} del valor operativo; los 10 años explícitos aportan {n(pv10)} millones. Es una proporción alta pero inferior al umbral de alerta de 85 % de la casa, lo que significa que el valor depende más de lo que se asuma sobre la fase madura que del ritmo de los próximos años.'))

def cap9():
    return chapter(9, 'Accionistas, dilución, recompras y gobierno',
    P(f'NVIDIA es una empresa dirigida por su fundador, Jensen Huang, quien es consejero delegado desde 1993; esa continuidad de la dirección es una ventaja de ejecución y a la vez una concentración de riesgo de personas clave que ninguna cifra de la hoja captura. No hay una valoración independiente del gobierno corporativo en esta revisión: se limita a lo que muestran los estados financieros sobre la asignación de capital.'),
    '<h3>Retorno de caja a los accionistas</h3>' + P(
      f'En el semestre la compañía recompró acciones por 39.044 millones y pagó dividendos por 6.290 millones, frente a 23.815 y 488 millones un año antes. El 18 de mayo de 2026 elevó el dividendo trimestral de 0,01 a 0,25 dólares por acción, es decir, 1,00 dólar anual, un rendimiento de 0,49 % sobre {usd(price)}. En los doce meses a julio de 2026 las recompras sumaron {n(buy[10])} millones y los dividendos {n(div[10])} millones, un total de {n(buy[10]+div[10])} millones, el {pc((buy[10]+div[10])/fcf[10],0)} del flujo de caja libre de {n(fcf[10])} millones. La política de devolución es agresiva en términos absolutos; en términos relativos deja una acumulación de caja y valores de más de 99.000 millones que el modelo suma al patrimonio al 100 % de su valor.'),
    '<h3>Dilución y compensación en acciones</h3>' + P(
      f'El número de acciones en circulación bajó de {n(IS[26][6])} millones al cierre del año fiscal {yrs[5]} a {n(IS[26][11])} millones en julio de 2026, un descenso neto de {pc(1-IS[26][11]/IS[26][6],1)} a pesar de la emisión por planes de compensación. Los premios pendientes son unidades de acciones restringidas (RSU), unidades por desempeño (PSU) y PSU basadas en mercado: 168 millones al 26 de julio de 2026 (0,7 % de las acciones), con un valor de concesión medio de 120,41 dólares y un gasto no reconocido de 19.400 millones que se reconocerá en 2,6 años. La compensación en acciones total fue de {n(sbc[10])} millones en los doce meses ({pc(sbc[10]/rev[10],1)} de los ingresos). No hay opciones de acciones pendientes que informar.'),
    '<h3>Cómo se trata en el modelo</h3>' + P(
      'La regla de la casa es restar los derechos pendientes del patrimonio una sola vez y no usar a la vez acciones diluidas que ya los incorporen. La hoja usa las 24.268 millones de acciones básicas en circulación. La parte ya devengada de los premios (alrededor de 4 % de los 168 millones, unos 7 millones de acciones, 0,03 % del patrimonio) es inmaterial y no se resta; el 96 % restante todavía no se ha ganado y su costo ya está dentro del gasto operativo del EBIT de los años futuros, donde la compensación en acciones se trata como un costo real. Declarar opciones habría sido incorrecto: NVIDIA no informa opciones pendientes y no hay valor que restar. Por eso el control de opciones de la hoja (celda B108) quedó VALIDADO con “No”, con la justificación documentada en la propia hoja.'),
    P('Una advertencia sobre las recompras: a 204,64 dólares por acción, cada dólar recomprado compra algo cuyo valor Base es casi idéntico al precio. La recompra es neutral para el valor por acción si el precio es igual al valor intrínseco, lo que ocurre aquí por construcción del caso Base; solo crea valor si el precio es inferior al valor y lo destruye si es superior, que es el caso del Conservador y la Disrupción.'))

def cap10():
    return chapter(10, 'Coste de capital, tasas y fechas',
    P(f'El costo de capital inicial de la hoja es {pc(wacc0,2)} y el terminal {pc(waccT,2)}. El costo del patrimonio resulta de la tasa libre de riesgo (5,29 %, Treasury a 10 años al 30 de septiembre de 2026, FRED), la prima de riesgo de acciones de Damodaran de octubre de 2026 (3,70 %), y una beta apalancada de 1,45 introducida como supuesto analítico: 5,29 % + 1,45 × 3,70 % = 10,66 %. El costo de la deuda antes de impuestos es 6,0 % (4,48 % después de la tasa marginal de 25,37 %) y el peso de la deuda en el valor de mercado es inferior a 1 % (38.860 millones de deuda frente a 4,97 billones de capitalización), por lo que el WACC es prácticamente el costo del patrimonio.'),
    '<h3>La decisión de fechas</h3>' + P(
      'El 30 de octubre de 2026 el Treasury a 10 años cerró en 4,94 %. Una versión previa de la hoja usaba esa tasa junto con la prima de riesgo de Damodaran de octubre de 3,70 %, que se calculó con 5,29 % (cierre del 30 de septiembre). Mezclar ambas fechas subestima el costo del patrimonio, porque la prima de Damodaran es la diferencia entre el rendimiento esperado del mercado y la tasa libre de riesgo de su propia fecha. Por eso se alineó el par publicado (5,29 % y 3,70 %) y el costo de capital terminal se fijó en la suma, 8,99 %, en lugar del 9,30 % escrito a mano. El efecto neto es +2,1 % sobre el valor Base (de 201,80 a 205,95 dólares): el mayor costo inicial resta valor y el menor costo terminal lo suma. Cuando Damodaran publique la prima de noviembre, con datos del 30 de octubre, deberán actualizarse tasa, prima y terminal a la vez.'),
    '<h3>Sensibilidad al costo de capital</h3>' + P(
      'La matriz de WACC por crecimiento terminal (Nivel 2, apartado 9) muestra que, con g de 3,5 %, una variación de ±50 puntos básicos en el WACC mueve el valor entre ' + usd(V['sensibilidadDCF']['matrices']['waccVsTerminalGrowth']['values'][3][2]) + ' y ' + usd(V['sensibilidadDCF']['matrices']['waccVsTerminalGrowth']['values'][1][2]) + ' por acción, y que a un WACC de ' + pc(V['sensibilidadDCF']['matrices']['waccVsTerminalGrowth']['rows'][1], 2) + ' el valor es ' + usd(V['sensibilidadDCF']['matrices']['waccVsTerminalGrowth']['values'][1][2]) + '. El valor es mucho más sensible al costo de capital que al ROIC terminal, como muestra la segunda matriz, donde mover el ROIC ±1 punto porcentual cambia el valor en menos de un dólar.'),
    P('El control técnico del WACC (celda B84 de la hoja de costo de capital) está VALIDADO, pero eso verifica coherencia aritmética y vinculación, no precisión económica. La beta de 1,45 no se ha contrastado con una regresión ni con una beta de negocio por sector; la deuda de mercado es un cálculo del modelo y no el valor razonable de los bonos; y la prima de riesgo del país es cero porque la empresa se considera estadounidense aunque cerca del 38 % de los ingresos tiene origen fuera de Estados Unidos. Son tres puntos a resolver en la auditoría económica.'))

def cap11():
    hs = [('Conservadora', cons), ('Base', base), ('Optimista', opt), ('Disrupción', disr)]
    rows = [[k, pc(r[1],1), usd(r[7]), usd(r[7]*(1-V['mos'])), pc(r[7]/price-1,0)] for k, r in hs]
    return chapter(11, 'Historias, probabilidades y señales de refutación',
    table(['Historia', 'Probabilidad', 'Valor por acción', 'Precio con MOS 35 %', 'vs. precio ' + usd(price)], rows, 'Cuatro historias de la hoja (Escenarios e historias).'),
    P(f'Las probabilidades suman 100 % entre las cuatro historias. El promedio ordinario usa solo Conservadora, Base y Optimista, con pesos renormalizados, y arroja {usd(ve)}; la Disrupción, con valor de {usd(disr[7])}, se informa aparte, de acuerdo con la regla del modelo, porque describe un deterioro de los fundamentos que no se promedia con los casos ordinarios.'),
    '<h3>Base (45 %): la expansión se normaliza sin ruptura</h3>' + P(
      f'Ingresos crecen {pc(base[2],1)} anual compuesto en cinco años, el margen baja a {pc(base[3],0)}, la razón ventas/capital es {n(base[4],1)} y luego {n(base[5],1)}. Señal de que se cumple: ingresos trimestrales por encima de 108.000 millones durante los próximos trimestres, margen bruto cercano a 75 % y compromisos de suministro que se convierten en ingresos. Señal de que falla: margen bruto por debajo de 70 % sin explicación de mezcla o crecimiento secuencial negativo en dos trimestres consecutivos.'),
    '<h3>Conservadora (22,5 %): el gasto se frena antes de lo previsto</h3>' + P(
      f'El crecimiento compuesto de cinco años es {pc(cons[2],1)}, el margen objetivo {pc(cons[3],0)} y la eficiencia de capital {n(cons[4],2)}. Representa clientes que digieren la capacidad ya instalada, mayor competencia de aceleradores propios y presión de precios. Su año 1 (387.802 millones) equivale a congelar los ingresos trimestrales en el nivel del trimestre de julio (384.884 millones anualizados), de modo que esta historia ya supone cero crecimiento secuencial desde el último trimestre reportado. Valor {usd(cons[7])}, {pc(1-cons[7]/price,0)} por debajo del precio actual: si ocurre, la acción pierde cerca de la mitad de su valor aun sin una crisis.'),
    '<h3>Optimista (22,5 %): la inferencia amplía el mercado</h3>' + P(
      f'Crecimiento de {pc(opt[2],1)} compuesto, margen {pc(opt[3],0)}, ventas/capital {n(opt[4],1)}, ROIC terminal {pc(opt[6],1)}. Supone que la demanda de inferencia, los sistemas de redes y el software multiplican el mercado y que la plataforma retiene precio. Valor {usd(opt[7])}. El ROIC terminal supera el 34 %: requiere que el foso de software y ecosistema se mantenga más de diez años, algo sin precedente en semiconductores.'),
    '<h3>Disrupción (10 %): ruptura competitiva o de demanda</h3>' + P(
      f'Crecimiento de {pc(disr[2],1)}, margen {pc(disr[3],0)}, ventas/capital {n(disr[4],2)}, g de {pc(disr[9],1)} y ROIC terminal {pc(disr[6],1)}. El mecanismo es causal: sustitución de GPU por aceleradores propios en cargas de inferencia, caída de precios y exceso de inventario y obligaciones de compra, con una recuperación lenta. No se libera capital cuando caen las ventas (política “Sin liberación”): los compromisos de suministro y la capacidad no se convierten en caja de forma automática. Valor {usd(disr[7])}.'),
    P('Las señales de refutación son medibles y públicas: margen bruto trimestral, crecimiento secuencial de ingresos, inventarios y obligaciones de compra de inventario en exceso, descuentos a clientes y evolución de los compromisos de suministro. Cada informe trimestral permite reasignar probabilidades sin alterar los supuestos de cada historia.'))

def cap12():
    rows = [['Valor operativo (suma de valores presentes)', n(pb['sumaPV'])], ['– Deuda (incluye arrendamientos GAAP)', n(pb['deuda'])], ['– Participaciones minoritarias', n(pb['minoritarios'])],
            ['+ Caja y valores negociables', n(pb['caja'])], ['+ Activos no operativos (valor contable)', n(pb['activosNoOperativos'])],
            ['= Valor del patrimonio', n(pb['valorPatrimonio'])], ['– Opciones', n(pb['opciones'])], ['Acciones (millones)', n(pb['acciones'])], ['Valor por acción', usd(pb['valorPorAccion'])]]
    return chapter(12, 'Valor intrínseco, MOS, precio y puente a equity',
    table(['Puente EV a patrimonio (millones de US$)', 'Valor'], rows, 'Valuation output, historia Base.'),
    P(f'El valor Base por acción es {usd(b35)}. Con un margen de seguridad de 35 % aplicado sobre el Base, el precio de entrada es {usd(mos)}. La cotización de {usd(price)} equivale al {pc(price/b35,1)} del valor Base, de modo que el mercado descuenta ligeramente menos que el caso central y exige un margen de seguridad adicional de {pc(1-mos/price,0)} frente al precio actual para cumplir la disciplina. A {usd(price)} la acción no está en zona de compra; la disciplina de la casa sugiere esperar.'),
    '<h3>Puente desde la revisión anterior (R4)</h3>' + P(
      'La revisión anterior valoraba la acción en 381,79 dólares y la actual en ' + usd(b35) + '. Al sustituir uno a uno los supuestos de R4 sobre la hoja actual, el valor cambia así: g terminal 3,5 % a 4,0 %: +9,31; tasa libre 4,94 % a 5,29 %: −3,97; costo de capital terminal 9,30 % a 8,99 %: +9,33; margen objetivo 53,0 % a 58,7 %: +22,11; ventas/capital: −2,26; senda de crecimiento de R4: +157,64; activos no operativos 47.898 a 39.257: −0,35. Queda un residuo de −11,82 hasta 381,79, que corresponde al costo de capital inicial de R4 (11,44 % frente a 10,66 %) y a diferencias de motor de cálculo. El 85 % de la diferencia está en la senda de ingresos. Como se explicó en el capítulo 3, la senda Base de A-1.2 es más prudente que la guía anualizada del emisor y esa prudencia explica por qué el valor es menor.'),
    '<h3>Qué descuenta el precio</h3>' + P(
      f'Con la tercera matriz de sensibilidad (crecimiento compuesto de los años 1 a 5 por margen objetivo), el precio de {usd(price)} corresponde casi exactamente al par Base (crecimiento {pc(base[2],1)}, margen {pc(base[3],0)}). Si el crecimiento compuesto fuese {pc(SD3["rows"][0],1)} con el mismo margen, el valor sería {usd(SD3["values"][0][2])}; con {pc(SD3["rows"][4],1)}, {usd(SD3["values"][4][2])}. Dicho de otro modo, el mercado descuenta un crecimiento compuesto de unos {pc(base[2],0)} anual durante cinco años a partir de un LTM de 302.970 millones, o sea, ingresos de unos {n(proy[4]["revenues"])} millones en el año 5. Lo que hay que creer para comprar al precio actual es exactamente el caso Base; para comprar con margen de seguridad hay que creer más que eso.'),
    '<h3>Activos no operativos y no duplicación</h3>' + P(
      'Los 47.898 millones de activos no operativos son el valor contable de valores de capital no cotizados (costo menos deterioro, más variaciones de precio observables). Se excluyen deliberadamente 3.300 millones de inversiones por método de participación en financiadores de infraestructura (financian la demanda de clientes) y 4.957 millones de capital cotizado bloqueado a largo plazo. La caja de 99.369 millones ya incluye 42.783 millones de valores de capital cotizado clasificados como negociables, y por eso no se repiten. Las ganancias y pérdidas de estas inversiones se registran en “otros ingresos, netos”, por debajo del resultado operativo: no están en el EBIT ni en el flujo del DCF, y por eso no hay solapamiento (celda B85 VALIDADA). El valor económico de estas inversiones es el contable porque no existe una valoración independiente: es una limitación que se declara.'))

def cap13():
    ms = ['EV/EBITDA', 'EV/FCFF', 'P/E', 'P/FCFE', 'P/OCF']
    rows = []
    for m in dm['metodos']:
        nm = m['nombre']; mt = mult_row(MT[nm], nm)
        rows.append([nm, pc(m['peso'],1), f'{n(mt[0],1)}x / {n(mt[1],1)}x / {n(mt[2],1)}x', n(ltm_mult[nm],1)+'x', usd(m['base']['vp'][2]), usd(m['base']['consolidado'])])
    return chapter(13, 'Múltiplos y sensibilidades',
    P('Los cinco múltiplos prioritarios (EV/EBITDA, EV/FCFF, P/E, P/FCFE y P/OCF) son aplicables a NVIDIA porque tiene beneficios, flujos de caja positivos y un denominador FY+3 positivo en todos los escenarios. P/S y P/BV se dejan fuera del cálculo: no añaden contraste fiable en una empresa cuyo margen es 65 % y cuyo patrimonio contable (228.984 millones) es una fracción del valor de mercado. Ninguno de los cinco tiene peso cero ni “PENDIENTE_ANCLA”.'),
    table(['Método', 'Peso total', 'Múltiplo de salida FY+3 (Cons. / Base / Opt.)', 'Múltiplo LTM', 'VP a 3 años (Base)', 'Consolidado hoy (Base)'], rows, 'Valoración por múltiplos descontada a valor presente (Descuento de múltiplos).'),
    '<h3>Cómo se eligió el múltiplo de salida</h3>' + P(
      'La regla de ciclo de la casa elige, para cada escenario, el múltiplo que NVIDIA tuvo en cierres fiscales cuyo crecimiento se parecía al que ese escenario espera en el año FY+3 (13 %, 22 % y 31 %), con los múltiplos históricos llevados al costo de capital actual, y limitado por el múltiplo que justifican los fundamentos (Damodaran) del propio escenario. Los pares (AVGO, QCOM y MU; TSM y AMD excluidos, el primero por la mezcla de moneda entre el ADR y los estados, el segundo por múltiplos distorsionados por amortización de adquisiciones) solo comprueban. Con esta regla el EV/EBITDA Base de salida es 20,8x frente a 24,4x LTM: NVIDIA ya no cotiza al múltiplo de los cierres fiscales 2024 y 2025 (41x a 43x) y la regla no lo extrapola, porque el crecimiento esperado en FY+3 es mucho menor que el de esos años.'),
    '<h3>Qué dicen y qué no dicen</h3>' + P(
      f'El valor por múltiplos consolidado a hoy es {usd(dm["multiplesHoy"]["base"])} en la Base, {pc(dm["multiplesHoy"]["base"]/b35-1,0)} por encima del DCF; el ponderado (60 % DCF, 40 % múltiplos) es {usd(dm["ponderadoHoy"]["base"])}. La categoría de empresa «Crecimiento», que fija esos pesos, es un juicio del analista. Hay tres cautelas. El P/E LTM de 25,9x está inflado por 30.399 millones de ingresos no operativos; el P/E Optimista supera en más de 25 % al P/E actual; y P/OCF y P/FCFE no restan la compensación en acciones (7.241 millones LTM). Las cinco matrices 5×5 de sensibilidad Base (apartado 10 del Nivel 2) calculan en la hoja y su centro coincide con el valor presente a tres años de cada método.'),
    P('La comparación con AZ Stocks, que debe mantenerse como contraste independiente y no mezclarse con el Método A-1.2, no se incorporó en esta revisión: queda pendiente y no se ha inventado ninguna cifra para suplirla.'))

def cap14():
    return chapter(14, 'Catalizadores, riesgos, fuentes y decisiones pendientes',
    '<h3>Catalizadores</h3>' + P('El primero es el 17 de noviembre de 2026, fecha de los resultados del tercer trimestre fiscal de 2027 (trimestre cerrado el 25 de octubre): permitirá contrastar la guía de 108.000 millones ±2 % y reasignar probabilidades. Siguen el ritmo de envíos de Vera Rubin, la evolución de los compromisos de suministro (279.000 millones), las decisiones de gasto de capital de los grandes compradores y cualquier cambio en las licencias de exportación a China.'),
    '<h3>Riesgos</h3>' + P('Concentración de clientes: cinco clientes directos representan 22 %, 14 %, 13 %, 11 % y 10 % de las cuentas por cobrar, es decir, 70 % del total. Suministro: dependencia de fundición, memoria y empaquetado de terceros, con restricciones declaradas. Regulación: restricciones de exportación y un arancel de 25 % sobre H200 importados que la compañía no puede trasladar. Competencia: aceleradores propios de los clientes. Financiación: la demanda depende de proyectos financiados con deuda y capital privado en los que NVIDIA también invierte. Valoración: el precio ya recoge el caso Base.'),
    '<h3>Salvedades abiertas de la valoración</h3>' + P('1) EN_REVISION sin auditoría económica. 2) Año 1 Base 1,8 % por debajo de la guía anualizada: el crecimiento a corto plazo puede estar subestimado. 3) Valor económico de las inversiones no operativas igual al contable. 4) Beta de 1,45 y costo de la deuda de 6 % no auditados. 5) Precio al 30 de octubre y tasas al 30 de septiembre, par de Damodaran de octubre; actualizar cuando se publique el de noviembre. 6) Múltiplos por regla de ciclo; categoría «Crecimiento» y MOS de 35 % son juicio del analista. 7) AZ Stocks pendiente. 8) QA visual autenticado pendiente.'),
    '<h3>Qué mueve el valor y cuánto</h3>' + P(
      f'Las matrices de sensibilidad permiten ordenar las hipótesis por su efecto sobre el valor Base de {usd(b35)}: cada punto porcentual de crecimiento compuesto en los años 1 a 5 vale unos {usd(DV_G)} por acción; cada punto de margen objetivo, unos {usd(DV_M)}; subir 50 puntos básicos el WACC resta {usd(abs(DV_W_UP))} y bajarlos suma {usd(DV_W_DN)}; medio punto menos de crecimiento perpetuo resta {usd(abs(DV_G_LO))} y medio punto más suma {usd(DV_G_HI)}. El crecimiento de los próximos cinco años y el costo de capital pesan mucho más que el ROIC terminal (medio punto de ROIC terminal mueve unos 0,3 dólares). Por eso la próxima publicación de resultados importa más por lo que revele sobre la trayectoria de ingresos que por cualquier cifra de margen.'),
    '<h3>Qué nos haría cambiar de opinión</h3>' + P('Subiría la probabilidad de la historia Optimista: crecimiento secuencial de ingresos superior a 12 % durante tres trimestres consecutivos con margen bruto estable en torno a 75 %, o evidencia de que el software y las redes representan una parte creciente de los ingresos con mayor margen. Subiría la probabilidad de la Conservadora: margen bruto que cae más de cinco puntos sin cambio de mezcla, aumento sostenido de inventarios y de obligaciones de compra de inventario en exceso por encima de los 2.138 millones actuales, o recortes de gasto de capital anunciados por varios de los grandes compradores a la vez. Activaría la Disrupción: pérdida pública de cuota en inferencia frente a aceleradores propios y descuentos de precio generalizados. En ninguno de los casos habría que alterar la estructura del modelo, solo las probabilidades y, si los datos lo justifican, el crecimiento de los dos primeros años.'),
    '<h3>Fuentes</h3>' + P('NVIDIA, Formulario 10-Q del segundo trimestre fiscal de 2027 (26 de julio de 2026, SEC, acceso 0001045810-26-000075); hoja de trabajo Método A-1.2 de NVDA y su captura con hash SHA-256 (<code>evidencia/captura-hoja-20261101</code>); Damodaran, prima implícita de octubre de 2026; FRED, serie DGS10; Yahoo Finance, cierres históricos y de pares; documentos del repositorio: CIERRE_GATES, MULTIPLOS_Y_PUENTE y FECHAS_TASAS (1 de noviembre de 2026).'))
